CREATE Proc [dbo].[GetMainStoreInventoryBalanceByItemUnit] @Sid as int as Select i.ItemId,i.Item,u.Unit,u.UId,ipl.Parlevel From Item i inner join ItemParLevel ipl on i.ItemId=ipl.ItemId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit u on iu.PurUnit=u.Uid where ipl.Sid = @SId and ipl.BRId=0group by i.ItemId,i.Item,u.Unit,u.UId,ipl.Parlevel--,iu.IssFactor,iu.PurFactor order by i.Item